      "arFull": "وَرَاوَدَتْهُ الَّتِیْ هُوَ فِیْ بَیْتِهَا عَنْ نَّفْسِهٖ وَغَلَّقَتِ الْاَبْوَابَ وَقَالَتْ هَیْتَ لَكَ ؕ قَالَ مَعَاذَ اللّٰهِ اِنَّهٗ رَبِّیْۤ اَحْسَنَ مَثْوَایَ ؕ اِنَّهٗ لَا یُفْلِحُ الظّٰلِمُوْنَ ۟",
      "ur": "اس عورت نے جس کے گھر میں یوسف تھے، یوسف کو بہلانا پھسلانا شروع کیا کہ وه اپنے نفس کی نگرانی چھوڑ دے اور دروازے بند کرکے کہنے لگی لو آجاؤ یوسف نے کہا اللہ کی پناه! وه میرا رب ہے، مجھے اس نے بہت اچھی طرح رکھا ہے۔ بے انصافی کرنے والوں کا بھلا نہیں ہوتا.[1]",
