      "arFull": "وَقَالَ نِسْوَةٌ فِی الْمَدِیْنَةِ امْرَاَتُ الْعَزِیْزِ تُرَاوِدُ فَتٰىهَا عَنْ نَّفْسِهٖ ۚ قَدْ شَغَفَهَا حُبًّا ؕ اِنَّا لَنَرٰىهَا فِیْ ضَلٰلٍ مُّبِیْنٍ ۟",
