      "arFull": "فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ اَرْسَلَتْ اِلَیْهِنَّ وَاَعْتَدَتْ لَهُنَّ مُتَّكَاً وَّاٰتَتْ كُلَّ وَاحِدَةٍ مِّنْهُنَّ سِكِّیْنًا وَّقَالَتِ اخْرُجْ عَلَیْهِنَّ ۚ فَلَمَّا رَاَیْنَهٗۤ اَكْبَرْنَهٗ وَقَطَّعْنَ اَیْدِیَهُنَّ وَقُلْنَ حَاشَ لِلّٰهِ مَا هٰذَا بَشَرًا ؕ اِنْ هٰذَاۤ اِلَّا مَلَكٌ كَرِیْمٌ ۟",
