      "arFull": "مَا تَعْبُدُوْنَ مِنْ دُوْنِهٖۤ اِلَّاۤ اَسْمَآءً سَمَّیْتُمُوْهَاۤ اَنْتُمْ وَاٰبَآؤُكُمْ مَّاۤ اَنْزَلَ اللّٰهُ بِهَا مِنْ سُلْطٰنٍ ؕ اِنِ الْحُكْمُ اِلَّا لِلّٰهِ ؕ اَمَرَ اَلَّا تَعْبُدُوْۤا اِلَّاۤ اِیَّاهُ ؕ ذٰلِكَ الدِّیْنُ الْقَیِّمُ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا یَعْلَمُوْنَ ۟",
