      "arFull": "یُوْسُفُ اَیُّهَا الصِّدِّیْقُ اَفْتِنَا فِیْ سَبْعِ بَقَرٰتٍ سِمَانٍ یَّاْكُلُهُنَّ سَبْعٌ عِجَافٌ وَّسَبْعِ سُنْۢبُلٰتٍ خُضْرٍ وَّاُخَرَ یٰبِسٰتٍ ۙ لَّعَلِّیْۤ اَرْجِعُ اِلَی النَّاسِ لَعَلَّهُمْ یَعْلَمُوْنَ ۟",
      "ur": "اے یوسف! اے بہت بڑے سچے یوسف! آپ ہمیں اس خواب کی تعبیر بتلایئے کہ سات موٹی تازی گائیں ہیں جنہیں سات دبلی پتلی گائیں کھا رہی ہیں اور سات بالکل سبز خوشے ہیں اور سات ہی دوسرے بالکل خشک ہیں، تاکہ میں واپس جاکر ان لوگوں سے کہوں کہ وه سب جان لیں.",
