      "arFull": "یٰبَنِیَّ اذْهَبُوْا فَتَحَسَّسُوْا مِنْ یُّوْسُفَ وَاَخِیْهِ وَلَا تَایْـَٔسُوْا مِنْ رَّوْحِ اللّٰهِ ؕ اِنَّهٗ لَا یَایْـَٔسُ مِنْ رَّوْحِ اللّٰهِ اِلَّا الْقَوْمُ الْكٰفِرُوْنَ ۟",
