      "arFull": "وَرَفَعَ اَبَوَیْهِ عَلَی الْعَرْشِ وَخَرُّوْا لَهٗ سُجَّدًا ۚ وَقَالَ یٰۤاَبَتِ هٰذَا تَاْوِیْلُ رُءْیَایَ مِنْ قَبْلُ ؗ قَدْ جَعَلَهَا رَبِّیْ حَقًّا ؕ وَقَدْ اَحْسَنَ بِیْۤ اِذْ اَخْرَجَنِیْ مِنَ السِّجْنِ وَجَآءَ بِكُمْ مِّنَ الْبَدْوِ مِنْ بَعْدِ اَنْ نَّزَغَ الشَّیْطٰنُ بَیْنِیْ وَبَیْنَ اِخْوَتِیْ ؕ اِنَّ رَبِّیْ لَطِیْفٌ لِّمَا یَشَآءُ ؕ اِنَّهٗ هُوَ الْعَلِیْمُ الْحَكِیْمُ ۟",
