      "arFull": "وَكَاَیِّنْ مِّنْ اٰیَةٍ فِی السَّمٰوٰتِ وَالْاَرْضِ یَمُرُّوْنَ عَلَیْهَا وَهُمْ عَنْهَا مُعْرِضُوْنَ ۟",
