      "arFull": "قُلْ هٰذِهٖ سَبِیْلِیْۤ اَدْعُوْۤا اِلَی اللّٰهِ ؔ۫ عَلٰی بَصِیْرَةٍ اَنَا وَمَنِ اتَّبَعَنِیْ ؕ وَسُبْحٰنَ اللّٰهِ وَمَاۤ اَنَا مِنَ الْمُشْرِكِیْنَ ۟",
      "ur": "آپ کہہ دیجئے میری راه یہی ہے۔ میں اور میرے متبعین اللہ کی طرف بلا رہے ہیں، پورے یقین اور اعتماد کے ساتھ۔[1] اور اللہ پاک ہے[2] اور میں مشرکوں میں نہیں.",
