      "number": 111,
      "arFull": "لَقَدْ كَانَ فِیْ قَصَصِهِمْ عِبْرَةٌ لِّاُولِی الْاَلْبَابِ ؕ مَا كَانَ حَدِیْثًا یُّفْتَرٰی وَلٰكِنْ تَصْدِیْقَ الَّذِیْ بَیْنَ یَدَیْهِ وَتَفْصِیْلَ كُلِّ شَیْءٍ وَّهُدًی وَّرَحْمَةً لِّقَوْمٍ یُّؤْمِنُوْنَ ۟۠",
